/**
 * Season results snapshot (`src/data/results/<year>.json`), generated by tools/openf1-results/export.mjs from OpenF1. Everything in it
 * is SOURCE data (official classifications and standings as published); nothing is computed. Derived metrics live in lib/drivers/stats.ts.
 */
export type ResultStatus = "FIN" | "DNF" | "DNS" | "DSQ" | "NC";

export interface ResultRow {
  acronym: string;
  number: number;
  team: string | null;
  /** Classified position; null when not classified (see status). */
  position: number | null;
  status: ResultStatus;
  /** Race and sprint only. */
  points?: number | null;
  laps?: number | null;
}

export interface SessionClassification {
  sessionKey: number;
  date: string;
  results: ResultRow[];
}

export interface Standing {
  acronym: string;
  position: number | null;
  points: number | null;
}

export interface SeasonEvent {
  round: number;
  meetingKey: number;
  name: string;
  location: string | null;
  countryCode: string | null;
  circuitShortName: string | null;
  date: string;
  race: SessionClassification;
  sprint: SessionClassification | null;
  qualifying: SessionClassification | null;
  /** Drivers' championship after this race, as published. */
  standings: Standing[] | null;
  /** Constructors' championship after this race, as published (absent in snapshots made before it was exported). */
  teamStandings?: Array<{ team: string; position: number | null; points: number | null }> | null;
}

export interface DriverIdentity {
  acronym: string;
  fullName: string | null;
  firstName: string | null;
  lastName: string | null;
  countryCode: string | null;
  numbers: number[];
  teams: Array<{ name: string; colour: string | null }>;
}

export interface SeasonResults {
  schema: "apex-f1/season-results@1";
  season: number;
  source: { name: string; url: string; endpoints: string[]; fetchedOn: string; note: string };
  scheduledRaces: number;
  /** Every scheduled race date has passed (the season is over), not "every race has a classification". */
  complete: boolean;
  events: SeasonEvent[];
  /** Past race dates with no published classification. Recorded as-is: the snapshot does not say why. */
  skipped?: Array<{ round: number; name: string; date: string; reason: string }>;
  drivers: DriverIdentity[];
}
